node -e 'const fs=require("fs")
const fail=(m)=>{console.error(m);process.exit(1)}
const norm=(s)=>s.replace(/\/\*[\s\S]*?\*\//g," ").replace(/^\s*\/\/.*$/gm," ")
const rd=(f)=>{try{return norm(fs.readFileSync(f,"utf8"))}catch(e){return null}}
const cu=rd("lib/ai/practice-curate.ts")
if(cu===null||!/FEATURE\s*=\s*.practice-curate./.test(cu))fail("Vera is never asked to fill an empty card hook or tags on a library practice, so a practice written without her stays thin (LIVE-644)")
if(!/withVoice\(/.test(cu))fail("the curation draft skips the voice primer, so its copy drifts from CONTENT-VOICE")
if(!/featureOverBudget\(FEATURE\)/.test(cu)||!/aiRateLimited\(FEATURE/.test(cu)||!(/recordAiUsage\(\{\s*feature:\s*FEATURE/.test(cu)||(/completeText\(\{\s*accounting:\s*\{\s*feature:\s*FEATURE/.test(cu)&&((/await settleAiAttempt\(/.test(rd("lib/ai/complete.ts")||"")&&/await reserveAiAttempt\(/.test(rd("lib/ai/complete.ts")||""))||(/await recordCompletion\(p\.accounting/.test(rd("lib/ai/complete.ts")||"")&&/await recordAiUsage\(\{\s*feature:\s*context\.feature/.test(rd("lib/ai/complete.ts")||""))))))fail("the curation draft is not gated, throttled and metered under its own key")
if(!/hook\s*&&\s*gaps\.hook/.test(cu)||!/gaps\.tags\s*&&/.test(cu))fail("the accept path writes without re-checking that the hook and tags are still empty, so a person-written hook can be replaced")
if(!/.practice-curate.\s*:\s*\d/.test(rd("lib/ai/budget.ts")||""))fail("practice-curate has no daily cap, so it inherits the fallback")
const ac=rd("app/(main)/admin/content/actions.ts")||""
if(!/draftPracticeCuration\(/.test(ac)||!/applyPracticeCuration\(/.test(ac))fail("no curator action asks for the draft or writes the accepted fill, so the module has no door")
const cl=rd("lib/practices/clean.ts")||""
if(!/\.or\(.summary\.is\.null/.test(cl)||!/reasons\.push\(.hookless.\)/.test(cl))fail("needs-attention reads only its least-used window, so a well-used practice with an empty card hook never reaches the panel and keeps it for ever")
if(!/includes\(.hookless.\)\s*\?\s*0/.test(cl))fail("an empty card hook does not sort first, so the panel row cap can hide it")
if(!/<CurateWithVera\b/.test(rd("components/widgets/practices/admin/needs-attention.tsx")||""))fail("the needs-attention panel offers no Vera fill, so a curator never sees the draft")
console.log("ok")'
